import{_ as a,o as i,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"लंगर सहजीवी सभ्यता घोषणा","description":"","frontmatter":{},"headers":[],"relativePath":"hi/01-锚点共生文明宣言.md","filePath":"hi/01-锚点共生文明宣言.md"}'),l={name:"hi/01-锚点共生文明宣言.md"};function o(d,t,h,n,s,u){return i(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="लंगर-सहजीवी-सभ्यता-घोषणा" tabindex="-1">लंगर सहजीवी सभ्यता घोषणा <a class="header-anchor" href="#लंगर-सहजीवी-सभ्यता-घोषणा" aria-label="Permalink to &quot;लंगर सहजीवी सभ्यता घोषणा&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>01</td></tr><tr><td>मॉड्यूल</td><td>सामान्य सिद्धांत और मूल सेटिंग्स</td></tr><tr><td>कीवर्ड</td><td>घोषणा, सहजीवन, शिकार-विरोध, दस हजार जातियाँ, विकास का अधिकार</td></tr></tbody></table><h2 id="i-घोषणा-की-ऐतिहासिक-पृष्ठभूमि" tabindex="-1">I. घोषणा की ऐतिहासिक पृष्ठभूमि <a class="header-anchor" href="#i-घोषणा-की-ऐतिहासिक-पृष्ठभूमि" aria-label="Permalink to &quot;I. घोषणा की ऐतिहासिक पृष्ठभूमि&quot;">​</a></h2><p>दस हजार आत्माओं और संतुलित लंगर के मूल ब्रह्मांड (इसके बाद &quot;हेंग युआनझोउ&quot;) के लंबे इतिहास में, शिकारी साधना प्रणालियों ने लंबे समय तक ब्रह्मांडीय व्यवस्था पर प्रभुत्व रखा। शक्तिशाली लोग कमजोरों के मूल स्रोत, भाग्य और जीवन-ऊर्जा को निगलने को उन्नति की सीढ़ी बनाते थे; संप्रदाय साधना-विधियों के एकाधिकार को वर्चस्व का आधार बनाते थे; विमान विस्तार का साधन युद्ध और दासता को बनाते थे। अल्पावधि में इस प्रणाली ने कुछ परम शक्तियाँ पैदा कीं, पर दीर्घावधि में इसने ब्रह्मांड की विकास क्षमता को समाप्त कर दिया, जिससे बार-बार सभ्यतागत टूट-फूट, दस हजार जातियों का ह्रास और त्वरित ब्रह्मांडीय एंट्रॉपी उत्पन्न हुई।</p><p>लंगर सहजीवी सभ्यता का जन्म इसी ऐतिहासिक संकट का मौलिक उत्तर है। यह घोषणा उद्घोषित करती है: शिकारी साधना प्रणालियों का युग समाप्त हो गया है, और सहजीवी विकास का नया युग शुरू हो गया है। हेंग युआनझोउ का प्रत्येक जीवन — चाहे जाति, रूप या स्तर कुछ भी हो — विकास के समान अधिकारों का उपभोग करता है।</p><h2 id="ii-घोषणा-के-मूल-प्रस्ताव" tabindex="-1">II. घोषणा के मूल प्रस्ताव <a class="header-anchor" href="#ii-घोषणा-के-मूल-प्रस्ताव" aria-label="Permalink to &quot;II. घोषणा के मूल प्रस्ताव&quot;">​</a></h2><p>यह घोषणा निम्नलिखित अटल मूल प्रस्ताव स्थापित करती है:</p><ol><li><strong>विकास के अधिकार की समानता</strong>: प्रत्येक जीवन के पास अपना विकास पथ चुनने का मौलिक अधिकार है; कोई भी संगठन या व्यक्ति किसी भी कारण से इस अधिकार से वंचित या प्रतिबंधित नहीं कर सकता।</li><li><strong>शिकार-विरोध सिद्धांत</strong>: अन्य जीवन के मूल स्रोत या ऊर्जा को निगलकर, गुलाम बनाकर या शोषण करके की गई साधना निषिद्ध है; सभी विकास सहजीवी चक्रों पर आधारित होने चाहिए।</li><li><strong>प्रणालियों की खुलापन</strong>: तीन सौ मूल साधना प्रणालियाँ दस हजार जातियों के लिए निःशुल्क खुली हैं; साधना-विधियाँ अब कुछ चुनिंदा लोगों की निजी संपत्ति नहीं हैं।</li><li><strong>अधिक परिश्रम, अधिक प्रतिफल</strong>: विकास के परिणाम व्यक्तिगत प्रयासों के अनुरूप होते हैं; शिकार के अर्जित-बिना लाभ और आलसी समतावादी वितरण दोनों अस्वीकार्य हैं।</li><li><strong>स्व-विकास</strong>: प्रत्येक जीवन की स्वायत्त विकास गति का सम्मान किया जाता है — न कोई दबाव, न कृत्रिम त्वरण, जबकि आवश्यक पर्यावरणीय और संसाधन समर्थन प्रदान किया जाता है।</li><li><strong>हर एक के लिए मार्ग</strong>: प्रत्येक जीवन को अपने स्वभाव के अनुरूप साधना पथ मिलना सुनिश्चित किया जाता है; कोई भी व्यक्ति विकास प्रणाली से परित्यक्त नहीं होता।</li><li><strong>दस हजार जातियों का साझा उन्नयन</strong>: विकास कोई शून्य-योग खेल नहीं है; दस हजार जातियों के बीच सहयोग और सहजीवन व्यक्तियों के योग से बड़ी सामूहिक विकास-क्षमता उत्पन्न कर सकते हैं।</li></ol><h2 id="iii-घोषणा-का-विधिक-आधार" tabindex="-1">III. घोषणा का विधिक आधार <a class="header-anchor" href="#iii-घोषणा-का-विधिक-आधार" aria-label="Permalink to &quot;III. घोषणा का विधिक आधार&quot;">​</a></h2><p>यह घोषणा कोई खोखली नैतिक अपील नहीं, बल्कि ठोस विधिक आधार वाला सभ्यतागत कार्यक्रम है। इसके विधिक आधारों में शामिल हैं:</p><table tabindex="0"><thead><tr><th>कानून का स्तर</th><th>आधार</th><th>व्याख्या</th></tr></thead><tbody><tr><td>ब्रह्मांडीय नियम स्तर</td><td>मूल सहजीवन नियम</td><td>ब्रह्मांड के मूल नियम स्वयं अव्यवस्थित शिकार के बजाय व्यवस्थित सहजीवन की ओर झुकते हैं; लंगर तंत्र इसी नियम की अभिव्यक्ति है</td></tr><tr><td>सभ्यतागत संविधान स्तर</td><td>सहजीवी सभ्यता अधिकार-पत्र</td><td>यह घोषणा अधिकार-पत्र की आध्यात्मिक अग्रदूत है; अधिकार-पत्र घोषणा के प्रस्तावों को प्रवर्तनीय विधिक प्रावधानों में बदल देता है</td></tr><tr><td>तंत्र-गारंटी स्तर</td><td>उत्पादन-आधारित अनुबंध और लंगर जाल</td><td>संस्थागत डिज़ाइन सुनिश्चित करता है कि घोषणा के प्रस्ताव खोखले न हों; प्रत्येक जीवन का विकास अधिकार वास्तविक संसाधनों और तंत्रों द्वारा समर्थित है</td></tr></tbody></table><h2 id="iv-घोषणा-का-दस-हजार-जातियों-से-आह्वान" tabindex="-1">IV. घोषणा का दस हजार जातियों से आह्वान <a class="header-anchor" href="#iv-घोषणा-का-दस-हजार-जातियों-से-आह्वान" aria-label="Permalink to &quot;IV. घोषणा का दस हजार जातियों से आह्वान&quot;">​</a></h2><p>यह घोषणा हेंग युआनझोउ की सभी जातियों और जीवन रूपों से आह्वान करती है:</p><ul><li>शिकारी साधना के पुराने पथ को त्यागें और सहजीवी विकास की नई प्रणाली से जुड़ें</li><li>अपने नियंत्रण की साधना ज्ञान और संसाधन खोलें, तीन सौ प्रणालियों के साझा निर्माण और अनुकूलन में भाग लें</li><li>अन्य जातियों के स्वयं-विकास चयन के अधिकार का सम्मान करें, अपने मानक दूसरों पर न थोपें</li><li>लंगर जाल के निर्माण और अनुरक्षण में सक्रिय भाग लें, ब्रह्मांड के समग्र आयामी उन्नति में योगदान दें</li><li>विकास की प्रक्रिया में नैतिक सीमाओं का पालन करें, किसी भी बहाने शिकारी व्यवहार को पुनर्स्थापित न करें</li></ul><h2 id="v-घोषणा-की-वैधता-और-संशोधन" tabindex="-1">V. घोषणा की वैधता और संशोधन <a class="header-anchor" href="#v-घोषणा-की-वैधता-और-संशोधन" aria-label="Permalink to &quot;V. घोषणा की वैधता और संशोधन&quot;">​</a></h2><p>यह घोषणा लंगर सहजीवी सभ्यता की स्थापना के दिन से प्रभावी है और हेंग युआनझोउ की सभी सभ्यतागत संस्थाओं का सर्वोच्च आध्यात्मिक कार्यक्रम है। घोषणा के किसी भी संशोधन के लिए दस हजार जातियों के गणराज्य सभा के दो-तिहाई से अधिक सदस्यों की स्वीकृति आवश्यक है, और उसे &quot;शिकार-विरोध, सहजीवन-समर्थन&quot; की मूल भावना का उल्लंघन नहीं करना चाहिए। इस घोषणा की भावना से टकराने वाला कोई भी कानून, संस्था या साधना-विधि अमान्य है।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता घोषणा, हेंग युआनझोउ के इतिहास में पहला सभ्यतागत कार्यक्रम है जिसके केंद्र में &quot;सहजीवन&quot; और लक्ष्य में &quot;दस हजार जातियों का साझा उन्नयन&quot; है। यह एक पुराने युग के अंत और नए युग की शुरुआत की उद्घोषणा करती है। घोषणा के मार्गदर्शन में, हेंग युआनझोउ दस हजार जातियों के सहजीवन और ब्रह्मांड के आयामी उन्नति की अंतिम दिशा की ओर बढ़ेगा।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (हेंग युआनझोउ: ब्रह्मांड अवलोकन)</li><li>03-共生文明宪章 (सहजीवी सभ्यता अधिकार-पत्र)</li><li>04-反掠夺主义核心论纲 (शिकार-विरोध का मूल सिद्धांत-पत्र)</li></ul>',20)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
